"use client";
import { useState, useEffect } from "react";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { useParams, useRouter } from "next/navigation";
import { createPrescription, getPrescriptions } from "@/app/api/doctor/prescription";

export default function NewPrescriptionPage() {
  const [medicines, setMedicines] = useState([
    { name: "", dosage: "", duration: "", notes: "" },
  ]);
  const [previousMedicines, setPreviousMedicines] = useState([]);
  const { id } = useParams();
  const router = useRouter();

  useEffect(() => {
    const fetchPrevious = async () => {
      try {
        const data = await getPrescriptions(id);
        if (Array.isArray(data)) {
          setPreviousMedicines(data);
        }
      } catch (err) {
        console.error("Error fetching previous prescription:", err);
      }
    };
    fetchPrevious();
  }, [id]);

  const handleMedicineChange = (idx, field, value) => {
    setMedicines((prev) =>
      prev.map((med, i) => (i === idx ? { ...med, [field]: value } : med))
    );
  };

  const addMedicine = () => {
    setMedicines((prev) => [...prev, { name: "", dosage: "", duration: "", notes: "" }]);
  };

  const removeMedicine = (idx) => {
    setMedicines((prev) => prev.filter((_, i) => i !== idx));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const prescriptionData = { patientId: id, medicines };
    try {
      await createPrescription(prescriptionData);
      alert("Prescription submitted successfully!");
      router.push(`/doctor/patients/history/${id}`);
    } catch (err) {
      console.error("Error submitting prescription:", err);
      alert("Failed to submit prescription.");
    }
  };
console.log("PreviousMedicines", previousMedicines);

  return (
    <div className="max-w-7xl mx-auto py-8 px-4 grid grid-cols-1 md:grid-cols-3 gap-6">
      
      <div className="md:col-span-2 space-y-6">
        <h1 className="text-2xl font-bold">New Prescription</h1>
        <Card className="rounded-xl p-6 shadow-md space-y-4 bg-white">
          <form onSubmit={handleSubmit} className="space-y-4">
            {medicines.map((med, idx) => (
              <div key={idx} className="border border-gray-200 rounded-lg p-4 space-y-2 bg-gray-50 relative">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block mb-1 text-sm font-medium text-gray-700">Medicine Name</label>
                    <Input value={med.name} onChange={(e) => handleMedicineChange(idx, "name", e.target.value)} required />
                  </div>
                  <div>
                    <label className="block mb-1 text-sm font-medium text-gray-700">Dosage</label>
                    <Input value={med.dosage} onChange={(e) => handleMedicineChange(idx, "dosage", e.target.value)} required />
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block mb-1 text-sm font-medium text-gray-700">Duration</label>
                    <Input value={med.duration} onChange={(e) => handleMedicineChange(idx, "duration", e.target.value)} required />
                  </div>
                  <div>
                    <label className="block mb-1 text-sm font-medium text-gray-700">Instructions</label>
                    <Textarea value={med.notes} onChange={(e) => handleMedicineChange(idx, "notes", e.target.value)} rows={2} required />
                  </div>
                </div>
                {medicines.length > 1 && (
                  <Button type="button" variant="outline" size="sm" className="absolute top-2 right-2" onClick={() => removeMedicine(idx)}>
                    Remove
                  </Button>
                )}
              </div>
            ))}
            <Button type="button" variant="secondary" onClick={addMedicine} className="w-full">
              + Add Another Medicine
            </Button>
            <Button type="submit" className="w-full rounded-lg">Submit Prescription</Button>
          </form>
        </Card>
      </div>

      {/* Right: Previous Prescriptions */}
      <div className="space-y-4">
        <h2 className="text-xl font-semibold text-blue-700">Previous Prescriptions</h2>
        {previousMedicines.length > 0 ? (
          <div className="space-y-4 overflow-y-auto max-h-[calc(100vh-150px)] pr-2">
            {previousMedicines.map((prescription, idx) => (
              <Card key={idx} className="p-4 bg-blue-50 border border-blue-200 rounded-xl">
                <div className="flex justify-between items-center mb-2">
                  <h3 className="text-sm font-semibold text-blue-800">Prescription #{idx + 1}</h3>
                  <span className="text-xs text-gray-600 italic">
                    {new Date(prescription.date).toLocaleDateString("en-IN", {
                      day: "numeric",
                      month: "short",
                      year: "numeric",
                    })}
                  </span>
                </div>
                <ul className="text-sm space-y-1">
                  {prescription.medicines.map((med, i) => (
                    <li key={i} className="text-gray-800">
                      <strong>{med.name}</strong> — {med.dosage}, {med.duration}
                      {med.notes && (
                        <div className="text-gray-600 italic">{med.notes}</div>
                      )}
                    </li>
                  ))}
                </ul>
              </Card>
            ))}
          </div>
        ) : (
          <p className="text-sm text-gray-500 italic">No previous prescriptions found.</p>
        )}
      </div>
    </div>
  );
}
